document.addEventListener("click",e=>{let t=e.target.closest("[data-hit]");t&&fetch("/hits/"+t.dataset.hit).catch(()=>{})});document.addEventListener("submit",e=>{let t=e.target;if(!t.id||t.id!=="link-create")return;let r=t.querySelector('input[name="url"]').value.trim(),i=t.querySelector('input[name="text"]').value.trim();(!r||!i)&&(e.preventDefault(),alert((r?"Title":"URL")+" is required"))});
